const categories=['전체','패션','뷰티','키즈','리빙','푸드'];
const products=[
{id:1,name:'에어 웜 라이트 후드 패딩',brand:'EVERYDAY STUDIO',cat:'패션',price:89000,old:139000,emoji:'🧥',color:'#eeefeb',rating:'4.9',reviews:128},
{id:2,name:'포근한 데일리 니트 가디건',brand:'SLOW MOMENT',cat:'패션',price:49000,old:79000,emoji:'👚',color:'#f3eee9',rating:'4.8',reviews:86},
{id:3,name:'글로우 에센셜 쿠션 세트',brand:'PURE RITUAL',cat:'뷰티',price:32000,old:48000,emoji:'🪞',color:'#f0eae5',rating:'4.9',reviews:203},
{id:4,name:'우리 아이 첫 데일리 백팩',brand:'LITTLE DAYS',cat:'키즈',price:39000,old:65000,emoji:'🎒',color:'#edf1e6',rating:'4.8',reviews:64},
{id:5,name:'내추럴 세라믹 머그 2P',brand:'ROOM & REST',cat:'리빙',price:24000,old:35000,emoji:'☕',color:'#ece8e1',rating:'4.9',reviews:97},
{id:6,name:'산지에서 온 제철 감귤 3kg',brand:'FRESH TABLE',cat:'푸드',price:18900,old:26000,emoji:'🍊',color:'#f8f0df',rating:'4.7',reviews:156},
{id:7,name:'소프트 베어 키즈 친구',brand:'LITTLE DAYS',cat:'키즈',price:25000,old:50000,emoji:'🧸',color:'#f1e9df',rating:'4.9',reviews:52},
{id:8,name:'보태니컬 핸드 & 바디 케어',brand:'PURE RITUAL',cat:'뷰티',price:28000,old:42000,emoji:'🧴',color:'#eaf0e9',rating:'4.8',reviews:118}];
const $=s=>document.querySelector(s);let state={cart:{},wish:[],recent:[],coupon:false};try{const s=JSON.parse(localStorage.getItem('jayoung-shop-v1'));if(s&&typeof s.cart==='object'&&Array.isArray(s.wish)&&Array.isArray(s.recent))state={...state,...s}}catch{};let active='전체',view='all',term='',slide=0,timer=null;
const money=n=>n.toLocaleString('ko-KR')+'원';const product=id=>products.find(p=>p.id===Number(id));function save(){localStorage.setItem('jayoung-shop-v1',JSON.stringify(state));$('#cartCount').textContent=Object.values(state.cart).reduce((a,b)=>a+b,0);$('#recentCount').textContent=state.recent.length}function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
$('#navLinks').innerHTML=['홈','쇼핑특가','패션','뷰티','키즈','리빙','푸드','베스트'].map((c,i)=>`<button class="${i===0?'active':''}" data-cat="${categories.includes(c)?c:'전체'}">${c}</button>`).join('');$('#allMenu').innerHTML=categories.map(c=>`<button data-cat="${c}">${c==='전체'?'전체 상품':c}</button>`).join('');$('#filters').innerHTML=categories.map(c=>`<button data-filter="${c}">${c}</button>`).join('');
const quick=[['🎟️','웰컴 쿠폰','coupon'],['✦','오늘의 특가','전체'],['🧥','아우터','패션'],['👟','패션','패션'],['🪞','뷰티','뷰티'],['🎒','키즈','키즈'],['🛋️','리빙','리빙'],['🍊','푸드','푸드'],['♡','찜한 상품','wish'],['🎁','이벤트','event']];$('#quickLinks').innerHTML=quick.map(([icon,label,cat])=>`<button data-quick="${cat}"><span>${icon}</span>${label}</button>`).join('');
function render(){let list=products.filter(p=>(active==='전체'||p.cat===active)&&(!term||(p.name+p.brand+p.cat).toLowerCase().includes(term))&&(view!=='wish'||state.wish.includes(p.id)));if($('#sort').value==='low')list.sort((a,b)=>a.price-b.price);if($('#sort').value==='high')list.sort((a,b)=>b.price-a.price);$('#productTitle').textContent=view==='wish'?'내가 찜한 좋은 발견':term?'검색 결과':active==='전체'?'지금, 눈여겨볼 발견':active+'에서 만나는 좋은 발견';$('#resultCount').textContent=list.length+'개의 상품';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===active));$('#productGrid').innerHTML=list.length?list.map(p=>`<article class="product-card"><button class="wish ${state.wish.includes(p.id)?'selected':''}" data-wish="${p.id}" aria-label="${p.name} 찜하기" aria-pressed="${state.wish.includes(p.id)}">${state.wish.includes(p.id)?'♥':'♡'}</button><button class="product-image" data-product="${p.id}" aria-label="${p.name} 상세 보기" style="background:${p.color}"><span class="label">${p.id%2?'BEST PICK':'NEW ARRIVAL'}</span><span class="emoji">${p.emoji}</span></button><p class="brand">${p.brand}</p><button class="product-name" data-product="${p.id}">${p.name}</button><p class="price"><span class="discount">${Math.round((1-p.price/p.old)*100)}%</span>${money(p.price)} <del>${money(p.old)}</del></p><span class="rating"><b>★ ${p.rating}</b> (${p.reviews})</span><button class="add" data-add="${p.id}">＋ 장바구니 담기</button></article>`).join(''):'<p class="empty">표시할 상품이 없습니다. 다른 검색어나 카테고리를 선택해 주세요.</p>'}
function filter(cat,scroll=true){active=cat;view='all';term='';$('#query').value='';render();$('#allMenu').hidden=true;$('#menuBtn').setAttribute('aria-expanded','false');if(scroll)$('#products').scrollIntoView({behavior:'smooth'})}
function openModal(title,html){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
function details(id){const p=product(id);if(!p)return;state.recent=[p.id,...state.recent.filter(i=>i!==p.id)].slice(0,8);save();openModal(p.name,`<div class="modal-product">${p.emoji}</div><p class="brand">${p.brand} · ${p.cat}</p><h3>${p.name}</h3><p>일상에 잘 어울리는 ${p.cat} 큐레이션 상품입니다. 현재는 쇼핑 기능을 체험할 수 있는 예시 상품입니다.</p><p class="price">${money(p.price)} <del>${money(p.old)}</del></p><button class="primary" data-add="${p.id}">장바구니에 담기</button>`)}
function cart(){const items=Object.entries(state.cart).filter(([id,q])=>product(id)&&q>0);openModal('장바구니',items.length?items.map(([id,q])=>{const p=product(id);return `<div class="list-item"><span>${p.emoji}</span><div class="item-info">${p.name}<br><small>${money(p.price)}</small></div><div class="qty"><button data-qty="${id}" data-delta="-1" aria-label="수량 줄이기">−</button>${q}<button data-qty="${id}" data-delta="1" aria-label="수량 늘리기">＋</button></div><button data-remove="${id}" aria-label="상품 삭제">×</button></div>`}).join('')+`<p class="total">합계 ${money(items.reduce((n,[id,q])=>n+product(id).price*q,0))}</p><p>예시 상품입니다. 실제 주문 및 결제는 제공하지 않습니다.</p><button class="primary" id="continueShopping">쇼핑 계속하기</button>`:'<p class="empty">아직 담은 상품이 없어요.<br>마음에 드는 좋은 발견을 담아 보세요.</p>')}
function coupon(){state.coupon=true;save();openModal('웰컴 쿠폰',`<div class="empty" style="background:#eef2e7;border-radius:12px"><strong style="font-size:40px;color:#3d5340">10% OFF</strong><p>웰컴 쿠폰을 보관했어요.</p><b>WELCOME10</b></div><p>쿠폰 보관 기능 시연입니다. 실제 구매 할인은 적용되지 않습니다.</p>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.cat)filter(d.cat);if(d.filter)filter(d.filter,false);if(d.product)details(d.product);if(d.add){state.cart[d.add]=(state.cart[d.add]||0)+1;save();toast('장바구니에 담았습니다.')}if(d.wish){const id=Number(d.wish);state.wish=state.wish.includes(id)?state.wish.filter(i=>i!==id):[...state.wish,id];save();render()}if(d.qty){state.cart[d.qty]=Math.max(0,(state.cart[d.qty]||0)+Number(d.delta));if(!state.cart[d.qty])delete state.cart[d.qty];save();cart()}if(d.remove){delete state.cart[d.remove];save();cart()}if(b.id==='continueShopping')$('#modal').close();if(d.quick){if(d.quick==='coupon')coupon();else if(d.quick==='wish')showWish();else if(d.quick==='event')openModal('시즌 이벤트','<h3>가을의 발견 WEEK</h3><p>시즌 아우터부터 우리 아이의 일상까지, 새로운 계절의 취향을 만나보세요.</p><p>현재 페이지의 행사와 혜택은 서비스 시연용 예시입니다.</p>');else filter(d.quick)}if(d.info){const info={account:['마이페이지','현재는 회원가입 없이 둘러보는 쇼핑 시연 서비스입니다. 찜한 상품과 장바구니는 이 브라우저에 저장됩니다. 실제 회원가입·로그인 기능은 아직 연결되지 않았습니다.'],orders:['주문·배송 안내','현재는 예시 상품을 사용하는 시연 서비스로 실제 주문과 배송은 진행되지 않습니다.'],support:['고객센터','JAYOUNG ON 쇼핑 서비스 안내입니다. 상품 검색, 카테고리 선택, 찜, 장바구니 기능을 체험할 수 있습니다. 실제 판매 관련 문의 채널은 아직 등록되지 않았습니다.']};openModal(...info[d.info])}});
function showWish(){view='wish';active='전체';term='';$('#query').value='';render();$('#products').scrollIntoView({behavior:'smooth'})}$('#wishBtn').onclick=showWish;$('#cartBtn').onclick=cart;$('#couponBtn').onclick=coupon;$('#recentBtn').onclick=()=>openModal('최근 본 상품',state.recent.length?state.recent.map(id=>{const p=product(id);return p?`<div class="list-item"><span>${p.emoji}</span><button class="item-info" data-product="${p.id}">${p.name}<br><small>${money(p.price)}</small></button></div>`:''}).join(''):'<p class="empty">최근 본 상품이 없습니다.</p>');$('#search').onsubmit=e=>{e.preventDefault();term=$('#query').value.trim().toLowerCase();active='전체';view='all';render();$('#products').scrollIntoView({behavior:'smooth'})};$('#sort').onchange=render;$('#menuBtn').onclick=()=>{$('#allMenu').hidden=!$('#allMenu').hidden;$('#menuBtn').setAttribute('aria-expanded',String(!$('#allMenu').hidden))};
function rotate(delta){slide=(slide+delta+3)%3;const hero=$('.hero');const cards=[...hero.children];if(innerWidth>700){if(delta>0)hero.append(cards[0]);else hero.prepend(cards[2])}else hero.scrollTo({left:slide*(cards[0].offsetWidth+12),behavior:'smooth'});$('#slideCount').innerHTML=`0${slide+1} <em>/ 03</em>`;$('.progress i').style.transform=`translateX(${slide*100}%)`}$('#next').onclick=()=>rotate(1);$('#prev').onclick=()=>rotate(-1);$('#pause').onclick=()=>{if(timer){clearInterval(timer);timer=null;$('#pause').textContent='▷';$('#pause').setAttribute('aria-label','자동 넘김 시작')}else{timer=setInterval(()=>rotate(1),5000);$('#pause').textContent='Ⅱ';$('#pause').setAttribute('aria-label','자동 넘김 정지')}};save();render();
